estilos.css_firma:
.m7 .pant{--ok:#0d7a5f;--amb:#b8860b;--rojo:#c0392b;--tinta:#14161c;--gris:#5a6070;--linea:#e2e4ea;--papel:#f4f5f7; --f-tit:"Anton","Barlow Condensed","Arial Narrow",sans-serif;--f-cond:"Barlow Condensed","Arial Narrow",sans-serif; --f-serif:"Source Serif 4",Georgia,serif;--f-txt:"Barlow",system-ui,sans-serif}
.m7 .duo{position:relative;background:var(--base);overflow:hidden}
.m7 .duo img{display:block;width:100%;height:100%;object-fit:cover;filter:grayscale(1) contrast(1.15);mix-blend-mode:luminosity;opacity:.92}
.m7 .duo::after{content:"";position:absolute;inset:0;background:var(--acento);mix-blend-mode:screen;opacity:.3;pointer-events:none}
.m7 .tapa .duo{position:absolute;inset:0}
.m7 .bn .duo{position:absolute;inset:0}
.m7 .bn .duo::after{opacity:.18}
.m7 .ev-foto .duo{position:absolute;inset:0}
.m7 .ev-foto .duo::after{opacity:.22}
.m7 .imgs .duo{width:72px;height:52px;border-radius:8px}
.m7 .previa .duo{position:absolute;inset:0}
.m7 .banda .duo{position:absolute;inset:0}
.m7 .banda .duo img{object-position:center 35%}
.m7 .tapa-velo{position:absolute;inset:0;background:linear-gradient(180deg,color-mix(in srgb,var(--base) 70%,transparent) 0%,transparent 26%,transparent 42%,color-mix(in srgb,var(--base) 92%,transparent) 78%,var(--base) 100%)}
.m7 .titular{padding:0 18px;display:flex;align-items:flex-end;gap:12px}
.m7 .titular-num{font-family:var(--f-tit);font-size:168px;line-height:.82;letter-spacing:-2px}
.m7 .titular-num small{font-size:84px;color:var(--acento-txt)}
.m7 .titular-lado{padding-bottom:10px;font-family:var(--f-cond);font-weight:700;font-size:24px;line-height:.95;text-transform:uppercase}
.m7 .ev-titular{margin:14px 18px 0;font-family:var(--f-tit);font-size:112px;line-height:.86;letter-spacing:-1.5px;color:#fff}
.m7 .ev-titular span{color:#ff8a7c}
.m7 .cab-sigla{font-family:var(--f-tit);font-size:44px;line-height:.9;letter-spacing:1px;text-transform:uppercase; padding-bottom:4px;border-bottom:3px solid var(--acento)}
.m7 .sec-tit{margin:0 0 10px;font-family:var(--f-tit);font-size:30px;line-height:1;text-transform:uppercase;letter-spacing:.3px}
.m7 .zoom img{animation:m7-zoom 22s cubic-bezier(.33,1,.68,1) infinite alternate;transform-origin:62% 40%}
@keyframes m7-zoom{from{transform:scale(1.02)}to{transform:scale(1.16) translate(-2%,1%)}}

.m8 .tel-pantalla, .m8 .pc-pantalla{background:#f2f3f6; color:#121722; font-family:"Barlow", system-ui, sans-serif;}
.m8 .zoc{display:flex; align-items:stretch; animation: m8-entra .7s cubic-bezier(.33,1,.68,1) both;}
.m8 .zoc-b{background:var(--acento); color:var(--tinta-acento); font-family:"Barlow Condensed",sans-serif; font-weight:700; font-size:13px; letter-spacing:1.5px; text-transform:uppercase; display:flex; align-items:center; padding:0 12px; white-space:nowrap;}
.m8 .zoc-t{background:#fff; color:#121722; padding:8px 14px 9px; flex:1; min-width:0; box-shadow:0 6px 18px rgba(0,0,0,.18);}
.m8 .zk .zoc-b{padding:5px 10px; font-size:12.5px;}
.m8 .zk .zoc-t{padding:10px 12px 12px;}
.m8 .zoc-b.rojo{background:#c0392b; color:#fff;}
.m8 .zoc-b.prim{background:var(--primario); color:#fff;}
.m8 .tick{display:flex; align-items:stretch; background:var(--base); color:#fff; overflow:hidden; height:38px;}
.m8 .tick-l{background:#c0392b; color:#fff; font-family:"Barlow Condensed",sans-serif; font-weight:800; font-size:15px; letter-spacing:1.5px; display:flex; align-items:center; padding:0 12px; position:relative; z-index:1;}
.m8 .tick-pista{display:flex; gap:36px; white-space:nowrap; padding-left:16px; animation: m8-corre 28s linear infinite; font-family:"Barlow Condensed",sans-serif; font-size:17px; font-weight:600; letter-spacing:.3px;}
.m8 .duo{position:relative; background:var(--base); overflow:hidden;}
.m8 .duo img{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; filter:grayscale(1) contrast(1.12); mix-blend-mode:luminosity; opacity:.88; animation: m8-ken 22s ease-in-out infinite alternate; transform-origin:60% 40%;}
.m8 .prev .duo{height:300px;}
.m8 .duo .tinte{position:absolute; inset:0; background:var(--acento); mix-blend-mode:screen; opacity:.32; pointer-events:none;}
.m8 .ev-foto .tinte{position:absolute; inset:0; background:var(--primario); mix-blend-mode:multiply; opacity:.35; pointer-events:none;}
.m8 .enc{display:flex; align-items:center; justify-content:space-between; gap:12px; background:var(--base); color:#fff; padding:8px 16px;}

.m9 .tel-pantalla, .m9 .pc-pantalla{--ok:#0d7a5f; --parcial:#b8860b; --mal:#c0392b; --tinta:#0d1220; --gris:#555d6e; --linea:#d9dce3; font-family:"Barlow", system-ui, sans-serif; color:var(--tinta); background:#f2f3f6;}
.m9 .marcador{display:grid; grid-template-columns:1fr 1fr; gap:4px;}
.m9 .mc{padding:14px 14px 12px; display:flex; flex-direction:column; justify-content:space-between; min-height:178px;}
.m9 .mc-bien{background:var(--ok); color:#fff;}
.m9 .mc-mal{background:var(--mal); color:#fff;}
.m9 .big{font-family:"Big Shoulders Display","Anton","Barlow Condensed",sans-serif; font-weight:900; line-height:.82; letter-spacing:-.5px; font-variant-numeric:tabular-nums;}
.m9 .mc .big{font-size:168px; animation:m9-entra .9s cubic-bezier(.33,1,.68,1) both;}
.m9 .ev-marc .mc .big{font-size:140px;}
.m9 .kpi{padding:14px 16px 14px; display:flex; flex-direction:column; justify-content:space-between; gap:8px; min-height:140px; color:#fff;}
.m9 .kpi .big{font-size:88px; animation:m9-entra .9s cubic-bezier(.33,1,.68,1) both;}
.m9 .k-base{background:var(--base);}
.m9 .k-prim{background:var(--primario);}
.m9 .k-acento{background:var(--acento); color:var(--tinta-acento);}
.m9 .k-ok{background:var(--ok);}
.m9 .enc{display:flex; align-items:center; justify-content:space-between; gap:12px; background:var(--base); color:#fff; padding:12px 16px;}

.m10 .tel-pantalla, .m10 .pc-pantalla{--m10-papel:#fbfcfd; --m10-blanco:#ffffff; --m10-tinta:#15181e; --m10-gris:#5a616d; --m10-gris2:#7a818c; --m10-linea:#dde1e7; --m10-linea2:#eceff3; --m10-ok:#0d7a5f; --m10-amb:#b8860b; --m10-rojo:#c0392b; --m10-serif:"Libre Caslon Text", Georgia, "Times New Roman", serif; --m10-cond:"Barlow Condensed", "Arial Narrow", sans-serif; --m10-sans:"Barlow", system-ui, -apple-system, "Segoe UI", sans-serif; background:var(--m10-papel); color:var(--m10-tinta); font-family:var(--m10-sans); font-size:15px; line-height:1.5;}
.m10 .obra .lamina{background:var(--m10-blanco);padding:14px;border:1px solid var(--m10-linea);box-shadow:0 1px 2px rgba(20,24,30,.05),0 14px 30px -18px rgba(20,24,30,.28)}
.m10 .obra .marco-img{overflow:hidden;background:#d9dce1}
.m10 .ini .obra .marco-img{aspect-ratio:4/3}
.m10 .epi{font-family:var(--m10-serif);font-style:italic;font-size:13.5px;line-height:1.45;color:var(--m10-gris)}
.m10 .rot{font-family:var(--m10-cond);font-weight:600;font-size:12.5px;letter-spacing:2.2px;text-transform:uppercase;color:var(--m10-gris)}
.m10 .bloque > .rot{display:block;padding-bottom:10px;border-bottom:1px solid var(--m10-tinta)}
.m10 .saludo h2{font-family:var(--m10-serif);font-weight:400;font-size:40px;line-height:1.05;margin:0;letter-spacing:-.5px}
.m10 .saludo h2 em{font-style:italic;text-decoration:underline;text-decoration-color:var(--acento);text-decoration-thickness:3px;text-underline-offset:7px}
.m10 .verd .frase{font-family:var(--m10-serif);font-size:31px;line-height:1.12;margin:0;letter-spacing:-.3px}

.m11 .tel-pantalla, .m11 .pc-pantalla{--ok:#0d7a5f; --ok-claro:#46c79c; --amb:#b8860b; --mal:#c0392b; --mal-claro:#ff8f82; --tinta:#141a2b; --gris:#535a6c; --gris-2:#767d8f; --linea: color-mix(in srgb, var(--base) 11%, #e9ebf0); --fondo: var(--base-claro); --carta:#fff; --sombra: 0 12px 28px -14px color-mix(in srgb, var(--base) 38%, transparent), 0 2px 6px -2px color-mix(in srgb, var(--base) 12%, transparent); --sombra-alta: 0 22px 44px -18px color-mix(in srgb, var(--base) 55%, transparent); --curva: cubic-bezier(.33,1,.68,1); font-family:"Figtree", system-ui, -apple-system, "Segoe UI", sans-serif; color:var(--tinta); background:var(--fondo);}
.m11 .medidor{display:grid; grid-template-columns:repeat(5, 1fr); gap:6px; margin:18px 0 8px;}
.m11 .seg{height:12px; border-radius:99px; background:var(--ok-claro); transform-origin:left center; animation:m11-llena .75s var(--curva) both;}
.m11 .seg.mal{background:var(--mal-claro);}
.m11 .resalte{color:var(--primario); background:linear-gradient(transparent 64%, color-mix(in srgb, var(--acento) 42%, transparent) 64%, color-mix(in srgb, var(--acento) 42%, transparent) 92%, transparent 92%); padding:0 2px;}
.m11 .principal::before{content:""; position:absolute; width:280px; height:280px; right:-110px; top:-130px; border-radius:50%; background:var(--primario); opacity:.55; filter:blur(10px); pointer-events:none;}
.m11 .medidor.claro .seg{background:var(--ok); height:14px;}
.m11 .medidor-rot{display:grid; grid-template-columns:repeat(5, 1fr); gap:6px; font-size:12px; font-weight:600; color:color-mix(in srgb, #fff 72%, transparent);}
.m11 .principal{position:relative; overflow:hidden; margin:18px 16px 0; border-radius:26px; padding:22px 22px 20px; color:#fff; background:var(--base); box-shadow:var(--sombra-alta); animation:m11-sube .7s var(--curva) both;}
.m11 .saludo h1, .m11 .gran-tit{margin:0; font-size:40px; font-weight:800; line-height:1.04; letter-spacing:-.025em; text-wrap:balance;}
.m11 .barra{position:sticky; bottom:14px; z-index:2; margin:26px 16px 16px; background:var(--base); border-radius:999px; display:grid; grid-template-columns:repeat(4, 1fr); gap:4px; padding:7px; box-shadow:0 18px 34px -12px color-mix(in srgb, var(--base) 70%, transparent);}

.m12 .tel-pantalla, .m12 .pc-pantalla{--negro:#000; --hoja:#0b0b0b; --hoja-2:#121212; --blanco:#fff; --gris-1:#cfcfcf; --gris-2:#a6a6a6; --gris-3:#8c8c8c; --linea:#262626; --linea-2:#3a3a3a; --uno: var(--acento-txt); --ok:#0d7a5f; --ok-luz:#3cc79a; --amb:#b8860b; --amb-luz:#e3ad36; --mal:#c0392b; --mal-luz:#ff6f61; --f-tit:"Anton","Bebas Neue","Arial Narrow",sans-serif; --f-txt:"Archivo",system-ui,-apple-system,"Segoe UI",sans-serif; --curva:cubic-bezier(.33,1,.68,1); background:var(--negro); color:var(--blanco); font-family:var(--f-txt); line-height:1.4;}
.m12 .uno{color:var(--uno); animation:m12-enciende 1.3s .75s var(--curva) both;}
.m12 .btn-uno{background:var(--uno); color:#000; animation:m12-enciende 1.3s .75s var(--curva) both;}
.m12 .tit{font-family:var(--f-tit); font-weight:400; text-transform:uppercase; letter-spacing:-.5px; line-height:.86;}
.m12 .tapa{position:relative; height:500px;}
.m12 .tapa-txt{position:absolute; left:0; right:0; bottom:0; padding:0 20px 6px; z-index:1;}
.m12 .foto::after{content:""; position:absolute; inset:0; background:linear-gradient(180deg, rgba(0,0,0,.35) 0%, rgba(0,0,0,0) 26%, rgba(0,0,0,.2) 52%, #000 96%); pointer-events:none;}
.m12 .seg{height:9px; background:var(--blanco); transform-origin:left; animation:m12-barra .7s var(--curva) both;}
.m12 .seg.mal{background:var(--mal-luz);}
.m12 .cifra{font-size:136px; margin-top:12px;}
.m12 .foto img, .m12 .foto video{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; filter:grayscale(1) contrast(1.6) brightness(.9); animation:m12-zoom 14s var(--curva) both;}
.m12 .cinco{display:grid; grid-template-columns:repeat(5,1fr); gap:5px; margin:24px 0 8px;}
.m12 .cinco-rot{display:grid; grid-template-columns:repeat(5,1fr); gap:5px; font-size:11px; font-weight:600; letter-spacing:.6px; text-transform:uppercase; color:var(--gris-3);}
@keyframes m12-enciende{from { filter:grayscale(1) brightness(1.6); } to { filter:grayscale(0) brightness(1); }}

.m13 .tel-pantalla, .m13 .pc-pantalla{--tinta:#111; --gris:#565656; --gris2:#6b6b6b; --tenue:#8a8a8a; --linea:#d6d6d6; --guia:#e9e9e9; --suave:#f4f4f4; --ok:#0d7a5f; --amb:#b8860b; --amb-txt:#7e5e09; --mal:#c0392b; --mal-txt:#ad2f20; --curva:cubic-bezier(.33,1,.68,1); position:relative; background:#fff; color:var(--tinta); font-family:"Archivo", "Helvetica Neue", Arial, sans-serif; font-variant-numeric:tabular-nums;}
.m13 .guia{position:absolute; inset:0; z-index:0; pointer-events:none; display:grid; grid-template-columns:repeat(6, minmax(0,1fr)); column-gap:var(--gap); padding-inline:var(--pad);}
.m13 .guia i{background:#fafafa; box-shadow:inset 1px 0 var(--guia), inset -1px 0 var(--guia); transform-origin:top center; animation:m13-guia 1.1s var(--curva) both;}
.m13 .guia ~ *{position:relative; z-index:1;}
.m13 .franja{height:6px; background:var(--primario); display:grid; grid-template-columns:repeat(6, minmax(0,1fr)); column-gap:var(--gap); padding-inline:var(--pad);}
.m13 .franja b{grid-column:5/7; background:var(--acento); margin-right:calc(var(--pad) * -1);}
.m13 .g{display:grid; grid-template-columns:repeat(6, minmax(0,1fr)); column-gap:var(--gap); padding-inline:var(--pad);}
@keyframes m13-guia{from { transform:scaleY(0); opacity:0; } to { transform:scaleY(1); opacity:1; }}

.m14 .tel-pantalla, .m14 .pc-pantalla{--g0:#0a0a0b; --g1:#111113; --g2:#161618; --g3:#1c1c1f; --g4:#232327; --ln:#232327; --ln2:#2e2e33; --ln3:#3a3a40; --t1:#ededed; --t2:#a1a1aa; --t3:#8e8e96; --ok:#4cc79f; --ok-f:#0d7a5f; --amb:#e3b341; --mal:#ff7b6e; --mal-f:#c0392b; --g: var(--acento-txt); --curva: cubic-bezier(.33,1,.68,1); --mono: "JetBrains Mono", ui-monospace, monospace; background:var(--g0); color:var(--t1); font-family:"Manrope", "Hanken Grotesk", system-ui, sans-serif; font-feature-settings:"ss01"; position:relative; isolation:isolate; -webkit-font-smoothing:antialiased;}
.m14 .resplandor{position:relative; isolation:isolate;}
.m14 .resplandor::before{content:""; position:absolute; z-index:-1; left:50%; top:46%; width:120%; height:140%; transform:translate(-50%,-50%); background:radial-gradient(closest-side, color-mix(in srgb, var(--mal-f) 30%, transparent), transparent 75%); filter:blur(14px); pointer-events:none; animation:m14-brilla 1.8s var(--curva) .6s both;}
.m14 .tex{position:absolute; inset:0 0 auto 0; height:var(--tex-h, 420px); overflow:hidden; z-index:-1; pointer-events:none; -webkit-mask-image:linear-gradient(to bottom, #000 0%, rgba(0,0,0,.55) 45%, transparent 100%); mask-image:linear-gradient(to bottom, #000 0%, rgba(0,0,0,.55) 45%, transparent 100%);}
.m14 .tex img{display:block; width:100%; height:100%; object-fit:cover; filter:grayscale(1) contrast(1.15) brightness(.85); opacity:.13;}
.m14 .tex::after{content:""; position:absolute; inset:0; background-image:linear-gradient(var(--ln) 1px, transparent 1px), linear-gradient(90deg, var(--ln) 1px, transparent 1px); background-size:32px 32px; opacity:.35; -webkit-mask-image:radial-gradient(ellipse at 70% 0%, #000 0%, transparent 70%); mask-image:radial-gradient(ellipse at 70% 0%, #000 0%, transparent 70%);}
.m14 .carta{background:linear-gradient(180deg, var(--g2), var(--g1)); border:1px solid var(--ln); border-radius:16px; box-shadow:inset 0 1px 0 rgba(255,255,255,.045), 0 20px 40px -24px #000;}
.m14 .hola h1{font-size:46px; font-weight:800; letter-spacing:-.045em; line-height:1;}
.m14 .hola h1 em{font-style:normal; color:var(--g);}

.m15 .tel-pantalla, .m15 .pc-pantalla{--tinta:#111; --gris:#5a5a5a; --gris-2:#6b6b6b; --linea:#d6d6d6; --linea-2:#ebebeb; --papel:#fff; --humo:#f2f2f2; --ok:#0d7a5f; --amb:#7a5a06; --amb-f:#b8860b; --mal:#c0392b; --mal-t:#a8301f; --forma:var(--primario); --curva:cubic-bezier(.33,1,.68,1); font-family:"Public Sans", system-ui, -apple-system, "Segoe UI", sans-serif; background:var(--papel); color:var(--tinta);}
.m15 .forma{background:var(--forma); color:#fff; position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; animation:m15-forma .9s var(--curva) both;}
.m15 .forma .gigante{font-family:"Unbounded", sans-serif; font-weight:900; line-height:.9; letter-spacing:-.04em; font-variant-numeric:tabular-nums;}
.m15 .compo .forma{position:absolute; left:0; top:28px; width:250px; height:250px;}
.m15 .bloque-domo .forma{width:100%; height:176px; padding-bottom:18px;}
.m15 .hola h1{margin:0; font-family:"Unbounded", sans-serif; font-weight:800; font-size:38px; line-height:1.02; letter-spacing:-.035em;}
.m15 .hola h1 span{color:var(--primario);}
@keyframes m15-forma{from { opacity:0; transform:scale(.72); } to { opacity:1; transform:scale(1); }}

.m16 .tel-pantalla, .m16 .pc-pantalla{--tinta:#15171c; --texto:#2d3037; --gris:#5a5e67; --filete:#e1e2e6; --filete-f:#c6c8ce; --ok:#0d7a5f; --mal:#c0392b; --amb:#8a6408; --curva:cubic-bezier(.33,1,.68,1); font-family:"Public Sans", system-ui, -apple-system, "Segoe UI", sans-serif; background:#fff; color:var(--texto); font-size:17px; line-height:1.55; -webkit-font-smoothing:antialiased;}
.m16 .margen{font-size:13px; font-weight:600; line-height:1.35; color:var(--gris); padding-top:5px;}
.m16 .fila{display:grid; grid-template-columns:72px minmax(0,1fr); column-gap:16px; padding:28px 20px; position:relative; animation:m16-entra .75s var(--curva) both; animation-delay:calc(var(--i,0) * 80ms);}
.m16 .fila + .fila::before, .m16 .pfila + .pfila::before{content:""; position:absolute; top:0; left:20px; right:20px; height:1px; background:var(--filete); transform-origin:left center; animation:m16-traza 1.1s var(--curva) both; animation-delay:calc(var(--i,0) * 80ms);}
.m16 .t-xl{margin:0; font-size:48px; font-weight:700; line-height:1.02; letter-spacing:-.03em; color:var(--tinta);}
.m16 .t-cifra{margin:0; font-size:56px; font-weight:700; line-height:1; letter-spacing:-.04em; color:var(--tinta);}
.m16 .lead{margin-top:12px; font-size:17px; color:var(--gris);}
.m16 .btn-linea{background:transparent; color:var(--tinta); box-shadow:inset 0 0 0 1px var(--filete-f);}
@keyframes m16-traza{from { transform:scaleX(0); } to { transform:scaleX(1); }}

.m17 .tel-pantalla, .m17 .pc-pantalla{--ok:#0d7a5f; --ok-txt:#0a6a52; --amb:#b8860b; --amb-txt:#7f5d08; --mal:#c0392b; --mal-txt:#ad3123; --no:#868c97; --tinta:#15171c; --gris:#5c616c; --chev:#b3b7bf; --fondo: color-mix(in srgb, var(--base) 6%, #eef0f3); --sep: color-mix(in srgb, var(--base) 10%, #e2e4e8); --curva: cubic-bezier(.33,1,.68,1); font-family:"Figtree", system-ui, -apple-system, "Segoe UI", sans-serif; color:var(--tinta); background:var(--fondo); -webkit-font-smoothing:antialiased;}
.m17 .grupo{list-style:none; margin:0; padding:0; background:#fff; border-radius:16px; overflow:hidden; box-shadow:0 1px 2px color-mix(in srgb, var(--base) 7%, transparent); animation:m17-sube .55s var(--curva) both; animation-delay:calc(var(--d, 0) * 90ms);}
.m17 .fila{position:relative; display:flex; align-items:center; gap:14px; min-height:60px; padding:10px 16px; color:inherit; text-decoration:none;}
.m17 .tabla .der{text-align:right;}
.m17 .tabla .der .dato{justify-content:flex-end;}

.m18 .tel-pantalla, .m18 .pc-pantalla{--negro:#0a0b09; --carbon:#131510; --carbon-2:#1a1d17; --carbon-3:#22261e; --linea:#2b3027; --linea-2:#3a4035; --texto:#f2f4ee; --gris:#a7ac9f; --gris-2:#8d9286; --fluor:#C6FF3D; --fluor-tinta:#0a0b09; --fluor-suave:color-mix(in srgb, #C6FF3D 14%, transparent); --ok:#4fd3a8; --amb:#f2b53c; --mal:#ff6e5e; --curva:cubic-bezier(.33,1,.68,1); --tit:"Unbounded", "Archivo", system-ui, sans-serif; font-family:"Familjen Grotesk", system-ui, -apple-system, "Segoe UI", sans-serif; background:var(--negro); color:var(--texto);}
