.m63 .riel-nom small{display:block; margin-top:4px; font-size:11px; font-weight:800; letter-spacing:1.2px; text-transform:uppercase; color:var(--acento-txt);}
.m63 .riel-pie{margin-top:auto; padding:18px 18px 0; border-top:1px solid color-mix(in srgb, #fff 10%, transparent); display:flex; align-items:center; gap:10px;}
.m63 .riel-pie div{font-size:13.5px; font-weight:700; line-height:1.25;}
.m63 .riel-pie small{display:block; font-size:12px; font-weight:600; color:color-mix(in srgb, #fff 72%, transparent);}
.m63 .banda{position:relative; background:var(--base); color:#fff; overflow:hidden; isolation:isolate;}
.m63 .banda-alta{padding-bottom:78px;}
.m63 .banda-foto{position:absolute; z-index:0; top:0; right:0; bottom:0; width:72%; margin:0; overflow:hidden; -webkit-mask-image:linear-gradient(to right, transparent 0, #000 58%); mask-image:linear-gradient(to right, transparent 0, #000 58%);}
.m63 .banda-foto img{display:block; width:100%; height:100%; object-fit:cover; object-position:60% 30%; filter:grayscale(1) contrast(1.05); mix-blend-mode:luminosity; opacity:.44; animation:m63-zoom 24s ease-in-out infinite alternate;}
.m63 .banda-foto::after{content:""; position:absolute; inset:0; background:linear-gradient(to top, var(--base) 0, transparent 60%);}
.m63 .medidor{display:grid; grid-template-columns:repeat(5, 1fr); gap:5px; margin-top:14px;}
.m63 .seg{height:8px; border-radius:4px; background:var(--ok); transform-origin:left center; animation:m63-llena .7s var(--curva) .25s both;}

.m64 .tel-pantalla, .m64 .pc-pantalla{--ok:#0d7a5f; --ok-t:#0a6a52; --amb:#b8860b; --amb-t:#73540a; --mal:#c0392b; --mal-t:#a42f22; --tinta:#17191e; --gris:#545a66; --gris2:#646a77; --papel:#f6f5f1; --carta:#fff; --linea:#e5e2da; --linea2:#efede7; --curva:cubic-bezier(.33,1,.68,1); --sombra:0 1px 2px rgba(23,25,30,.05), 0 8px 24px -16px rgba(23,25,30,.28); font-family:"Hanken Grotesk", system-ui, -apple-system, "Segoe UI", sans-serif; color:var(--tinta); background:var(--papel);}
.m64 .mosaico{display:grid; grid-template-columns:1.32fr 1fr 1fr; gap:6px;}
.m64 .mosaico .f1{grid-column:1; grid-row:1 / span 2; border-radius:20px 6px 6px 20px;}
.m64 .mosaico .f2{grid-column:2 / span 2; grid-row:1; border-radius:6px 20px 6px 6px;}
.m64 .mosaico .f3{grid-column:2; grid-row:2;}
.m64 .mosaico .f4{grid-column:3; grid-row:2; border-radius:6px 6px 20px 6px;}
.m64 .mosaico .ft{animation:m64-tesela .9s var(--curva) both;}
.m64 .mosaico .f2{animation-delay:.08s;}
.m64 .mosaico .f3{animation-delay:.16s;}
.m64 .mosaico .f4{animation-delay:.24s;}
.m64 .mosaico .f1 img{animation:m64-lento 22s ease-in-out infinite alternate;}
.m64 .ft{position:relative; overflow:hidden; background:var(--base); border-radius:6px;}
.m64 .ft img{display:block; width:100%; height:100%; object-fit:cover; filter:grayscale(1) contrast(1.03) brightness(1.05); opacity:.94;}
.m64 .ft::after{content:""; position:absolute; inset:0; background:var(--primario); mix-blend-mode:color; opacity:.16; pointer-events:none;}
.m64 .rotulo-foto{position:absolute; z-index:2; left:14px; right:10px; bottom:12px; color:#fff; font-family:"Barlow Condensed", "Arial Narrow", sans-serif; font-weight:700; font-size:22px; line-height:1; text-transform:uppercase; letter-spacing:.3px;}
.m64 .portada{padding:14px 16px 0;}
.m64 .portada .mosaico{grid-template-rows:134px 116px;}
.m64 .portada .f1::before{content:""; position:absolute; inset:45% 0 0; z-index:1; background:linear-gradient(transparent, rgba(10,12,16,.62)); pointer-events:none;}

.m65 .tel-pantalla, .m65 .pc-pantalla{--ok:#0d7a5f; --ok-txt:#0b6b53; --amb:#b8860b; --amb-txt:#7a5a07; --mal:#c0392b; --mal-txt:#a8321f; --tinta:#171a21; --gris:#555b67; --gris-2:#8a909b; --linea: color-mix(in srgb, var(--base) 9%, #e4e6ea); --linea-suave: color-mix(in srgb, var(--base) 5%, #eef0f2); --fondo: color-mix(in srgb, var(--base) 4%, #f5f6f8); --papel:#ffffff; --marca-suave: color-mix(in srgb, var(--primario) 9%, #fff); --sombra: 0 1px 2px rgba(20,24,32,.05), 0 10px 26px -16px rgba(20,24,32,.22); --sombra-hoja: 0 1px 1px rgba(20,24,32,.07), 0 8px 16px -8px rgba(20,24,32,.16), 0 34px 60px -28px color-mix(in srgb, var(--base) 50%, transparent); --curva: cubic-bezier(.33,1,.68,1); font-family:"Public Sans", system-ui, -apple-system, "Segoe UI", sans-serif; color:var(--tinta); background:var(--fondo);}
.m65 .tilde{display:block;}
.m65 .tilde path{fill:none; stroke:var(--ok); stroke-width:2.7; stroke-linecap:round; stroke-linejoin:round; stroke-dasharray:1; stroke-dashoffset:0; animation:m65-traza .45s var(--curva) both;}
.m65 .ronda{position:absolute; left:-13px; top:-8px; width:calc(100% + 26px); height:calc(100% + 16px); overflow:visible; pointer-events:none;}
.m65 .ronda path{fill:none; stroke:var(--mal); stroke-width:2.2; stroke-linecap:round; stroke-dasharray:1; stroke-dashoffset:0; animation:m65-traza .8s var(--curva) both;}
.m65 .papelito{width:96px; height:116px; background:var(--papel); border-radius:3px; transform:rotate(4deg); margin-top:2px; box-shadow:0 1px 1px rgba(20,24,32,.08), 0 10px 20px -10px color-mix(in srgb, var(--base) 50%, transparent); outline:1px solid var(--linea-suave); padding:11px 9px; position:relative;}
.m65 .papelito i{display:block; height:4px; border-radius:2px; background:#e3e5e9; margin-bottom:7px; position:relative;}
.m65 .papelito i.t{width:58%; background:color-mix(in srgb, var(--primario) 35%, #fff); margin-bottom:10px;}
.m65 .papelito i.l{width:70%;}
.m65 .papelito i.c{width:46%;}
.m65 .papelito .pm{position:absolute; right:7px; width:13px; height:13px;}
.m65 .papelito .pm path{stroke-width:3.4;}
.m65 .papelito .pr{position:absolute; left:46px; top:76px; width:42px; height:15px; overflow:visible;}
.m65 .papelito .pr path{fill:none; stroke:var(--mal); stroke-width:2; stroke-linecap:round; stroke-dasharray:1; animation:m65-traza .7s .9s var(--curva) both;}
.m65 .hoja{background:var(--papel); border-radius:3px; box-shadow:var(--sombra-hoja); padding:18px 16px 20px; transform:rotate(-1.1deg); position:relative; animation:m65-hoja .9s var(--curva) both;}
.m65 .hoja::before{content:""; position:absolute; left:0; right:0; top:0; height:4px; background:repeating-linear-gradient(90deg, var(--linea) 0 6px, transparent 6px 10px); opacity:.9;}
.m65 .mesa{margin-top:-108px; padding:0 22px 6px; position:relative; z-index:1;}
@keyframes m65-traza{from { stroke-dashoffset:1; } to { stroke-dashoffset:0; }}

.m66 .tel-pantalla, .m66 .pc-pantalla{--ok:#0d7a5f; --ok-txt:#0a6a52; --amb:#b8860b; --amb-txt:#7a5a06; --mal:#c0392b; --mal-txt:#a8321f; --tinta:#171a21; --gris:#555c6b; --gris-2:#6a7180; --linea:#e3e5ea; --linea-2:#eef0f3; --fondo:color-mix(in srgb, var(--base) 3%, #f7f7f6); --carta:#fff; --marca-txt:color-mix(in srgb, var(--primario) 78%, var(--base)); --boton:color-mix(in srgb, var(--primario) 80%, var(--base)); --suave:color-mix(in srgb, var(--primario) 7%, #fff); --sombra:0 1px 2px color-mix(in srgb, var(--base) 6%, transparent), 0 10px 24px -18px color-mix(in srgb, var(--base) 30%, transparent); --curva:cubic-bezier(.33,1,.68,1); --cond:"Barlow Condensed", "Arial Narrow", sans-serif; font-family:"Hanken Grotesk", system-ui, -apple-system, "Segoe UI", sans-serif; color:var(--tinta); background:var(--fondo);}
.m66 .e{animation:m66-entra .72s var(--curva) both; animation-delay:calc(var(--i, 0) * 80ms + 60ms);}
@keyframes m66-entra{from { opacity:0; transform:translateY(8px); } to { opacity:1; transform:none; }}
.m66 .clip-carta{margin:18px 16px 0; padding:10px;}
.m66 .clip{position:relative; height:150px; border-radius:12px; overflow:hidden; background:var(--base-claro);}
.m66 .clip img, .m66 .clip video{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; filter:grayscale(1) contrast(.94) brightness(1.08); opacity:.92;}
.m66 .clip::after{content:""; position:absolute; inset:0; background:var(--primario); mix-blend-mode:color; opacity:.5; pointer-events:none;}
.m66 .clip-pie{display:flex; align-items:center; justify-content:space-between; gap:10px; padding:12px 6px 4px;}
.m66 .clip-pie b{display:block; font-size:15px; font-weight:700; line-height:1.25;}
.m66 .clip-pie span{font-size:13.5px; color:var(--gris);}
.m66 .en-vivo{display:inline-flex; align-items:center; gap:6px; font-size:12.5px; font-weight:700; color:var(--gris); white-space:nowrap;}
.m66 .en-vivo::before{content:""; width:7px; height:7px; border-radius:50%; background:var(--acento); box-shadow:0 0 0 3px color-mix(in srgb, var(--acento) 22%, transparent);}
.m66 .carta{background:var(--carta); border-radius:18px; box-shadow:var(--sombra); border:1px solid var(--linea-2);}
